    for row in left.get('facts',[])+right.get('facts',[]):
        add_unique(facts,row)
    for row in left.get('negative_givens',[])+right.get('negative_givens',[]):
        add_unique(negatives,row)
    for row in left.get('witnesses',[])+right.get('witnesses',[]):
        add_unique(witnesses,row)
    for reason in left.get('reasons',[])+right.get('reasons',[]):
        add_unique(reasons,reason)
    return part(facts,negatives,witnesses,left.get('complete') is True and right.get('complete') is True,reasons)


